/bin/bash -lc "~/.venv/bin/python - <<'PY'
import onnx
from onnx import helper,TensorProto
for op in ['Crop','ImageScaler','Upsample','Affine','ConstantFill']:
 try:
  s=onnx.defs.get_schema(op,max_inclusive_version=12)
  print(op,'schema',s.since_version,'deprecated',s.deprecated)
 except Exception as e: print(op,'no schema',e)

def test(op, attrs, outshape, inputs=['input']):
 x=helper.make_tensor_value_info('input',TensorProto.FLOAT,[1,10,30,30]); y=helper.make_tensor_value_info('output',TensorProto.FLOAT,outshape)
 n=helper.make_node(op,inputs,['output'],**attrs); m=helper.make_model(helper.make_graph([n],'g',[x],[y]),ir_version=10,opset_imports=[helper.make_opsetid('',12)])
 print('\\n',op)
 try: onnx.checker.check_model(m,full_check=True); print('checker ok')
 except Exception as e: print('checker fail',e)
 try:
  import onnxruntime as ort
  s=ort.InferenceSession(m.SerializeToString()); print('ort ok',s.get_outputs()[0].shape)
 except Exception as e: print('ort fail',e)
test('Crop',{'border':[0,9,27,0]},[1,1,3,3])
test('ImageScaler',{'scale':1.0,'bias':[0.0]*10},[1,10,30,30])
PY"

